     1	package br.com.marealta.reservas.domain;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	import java.util.Optional;
     6	
     7	public class ReservationService {
     8	    private final RoomCatalog rooms;
     9	    private final List<ReservationListener> listeners;
    10	    private final List<Reservation> reservations = new ArrayList<>();
    11	
    12	    public ReservationService(RoomCatalog rooms, List<ReservationListener> listeners) {
    13	        this.rooms = rooms;
    14	        this.listeners = List.copyOf(listeners);
    15	    }
    16	
    17	    public synchronized Reservation create(NewReservation request) {
    18	        Room room = rooms.find(request.roomNumber())
    19	                .orElseThrow(() -> DomainException.roomNotFound(request.roomNumber()));
    20	        if (request.guests() > room.capacity()) throw DomainException.capacityExceeded(room.capacity());
    21	        boolean taken = reservations.stream().anyMatch(r -> r.overlaps(room, request.checkIn(), request.checkOut()));
    22	        if (taken) throw DomainException.roomUnavailable(room.number());
    23	        Reservation reservation = new Reservation(reservations.size() + 1, room, request);
    24	        reservations.add(reservation);
    25	        return reservation;
    26	    }
    27	
    28	    public synchronized Reservation confirm(String id) {
    29	        Reservation reservation = get(id);
    30	        reservation.confirm();
    31	        listeners.forEach(l -> l.onConfirmed(reservation));
    32	        return reservation;
    33	    }
    34	
    35	    public synchronized Reservation cancel(String id) {
    36	        Reservation reservation = get(id);
    37	        ReservationStatus previous = reservation.status();
    38	        reservation.cancel();
    39	        listeners.forEach(l -> l.onCancelled(reservation, previous));
    40	        return reservation;
    41	    }
    42	
    43	    public synchronized Reservation checkIn(String id) {
    44	        Reservation reservation = get(id);
    45	        reservation.startStay();
    46	        return reservation;
    47	    }
    48	
    49	    public synchronized Reservation checkOut(String id) {
    50	        Reservation reservation = get(id);
    51	        reservation.endStay();
    52	        return reservation;
    53	    }
    54	
    55	    /** Second copy of the receipt; only exists for paid reservations. */
    56	    public synchronized Reservation paidReservation(String id) {
    57	        Reservation reservation = get(id);
    58	        if (!reservation.status().isPaid()) {
    59	            throw DomainException.operationNotAllowed("Comprovante só existe para reserva paga");
    60	        }
    61	        return reservation;
    62	    }
    63	
    64	    public synchronized Reservation get(String id) {
    65	        return find(id).orElseThrow(() -> DomainException.reservationNotFound(id));
    66	    }
    67	
    68	    public synchronized List<Reservation> all() {
    69	        return List.copyOf(reservations);
    70	    }
    71	
    72	    private Optional<Reservation> find(String id) {
    73	        try {
    74	            int number = Integer.parseInt(id);
    75	            return number >= 1 && number <= reservations.size()
    76	                    ? Optional.of(reservations.get(number - 1)) : Optional.empty();
    77	        } catch (NumberFormatException e) {
    78	            return Optional.empty();
    79	        }
    80	    }
    81	}
