     1	package br.com.marealta.reservas.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public class Reservation {
     7	    private final int id;
     8	    private final Room room;
     9	    private final NewReservation request;
    10	    private final Quote quote;
    11	    private ReservationStatus status = ReservationStatus.PENDING;
    12	    private BigDecimal amountPaid = Money.ZERO;
    13	    private BigDecimal refund;
    14	
    15	    public Reservation(int id, Room room, NewReservation request) {
    16	        this.id = id;
    17	        this.room = room;
    18	        this.request = request;
    19	        this.quote = Quote.of(room, request.checkIn(), request.checkOut(), request.ratePlan());
    20	    }
    21	
    22	    public void confirm() {
    23	        require(status == ReservationStatus.PENDING, "Só é possível confirmar uma reserva pendente");
    24	        status = ReservationStatus.CONFIRMED;
    25	        amountPaid = quote.total();
    26	    }
    27	
    28	    public void startStay() {
    29	        require(status == ReservationStatus.CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada");
    30	        status = ReservationStatus.CHECKED_IN;
    31	    }
    32	
    33	    public void endStay() {
    34	        require(status == ReservationStatus.CHECKED_IN, "Só é possível fazer check-out de quem fez check-in");
    35	        status = ReservationStatus.CHECKED_OUT;
    36	    }
    37	
    38	    public void cancel() {
    39	        require(status == ReservationStatus.PENDING || status == ReservationStatus.CONFIRMED,
    40	                "Só é possível cancelar uma reserva pendente ou confirmada");
    41	        status = ReservationStatus.CANCELLED;
    42	        refund = request.ratePlan().refundOf(amountPaid);
    43	    }
    44	
    45	    private void require(boolean allowed, String message) {
    46	        if (!allowed) throw DomainException.operationNotAllowed(message);
    47	    }
    48	
    49	    public boolean overlaps(Room other, LocalDate in, LocalDate out) {
    50	        return status != ReservationStatus.CANCELLED && room.equals(other)
    51	                && checkIn().isBefore(out) && in.isBefore(checkOut());
    52	    }
    53	
    54	    public boolean occupiesNight(LocalDate night) {
    55	        return status.isPaid() && !night.isBefore(checkIn()) && night.isBefore(checkOut());
    56	    }
    57	
    58	    /** What stayed with the inn: paid minus refunded. */
    59	    public BigDecimal retained() {
    60	        return refund == null ? amountPaid : Money.round(amountPaid.subtract(refund));
    61	    }
    62	
    63	    public int id() { return id; }
    64	    public Room room() { return room; }
    65	    public String guestName() { return request.guestName(); }
    66	    public String guestEmail() { return request.guestEmail(); }
    67	    public String guestCpf() { return request.guestCpf(); }
    68	    public LocalDate checkIn() { return request.checkIn(); }
    69	    public LocalDate checkOut() { return request.checkOut(); }
    70	    public int guests() { return request.guests(); }
    71	    public RatePlan ratePlan() { return request.ratePlan(); }
    72	    public int nights() { return quote.nights(); }
    73	    public BigDecimal subtotal() { return quote.subtotal(); }
    74	    public BigDecimal discount() { return quote.discount(); }
    75	    public BigDecimal total() { return quote.total(); }
    76	    public ReservationStatus status() { return status; }
    77	    public BigDecimal amountPaid() { return amountPaid; }
    78	    public BigDecimal refund() { return refund; }
    79	}
