     1	package br.com.marealta.reservas.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.format.DateTimeFormatter;
     6	
     7	public record Receipt(String title, int reservationId, String guestName, String guestCpf, int roomNumber,
     8	                      RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights,
     9	                      BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    10	
    11	    public static final String TITLE = "Comprovante de reserva";
    12	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    13	
    14	    public static Receipt of(Reservation r) {
    15	        return new Receipt(TITLE, r.id(), r.guestName(), r.guestCpf(), r.room().number(), r.room().type(),
    16	                r.checkIn(), r.checkOut(), r.nights(), r.subtotal(), r.discount(), r.total());
    17	    }
    18	
    19	    public static String date(LocalDate date) {
    20	        return date.format(DATE);
    21	    }
    22	
    23	    public String text() {
    24	        StringBuilder text = new StringBuilder();
    25	        text.append(title).append(" nº ").append(reservationId).append('\n');
    26	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    27	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    28	        text.append("Entrada: ").append(date(checkIn)).append(" | Saída: ").append(date(checkOut))
    29	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
    30	        text.append("Diárias: ").append(Money.format(subtotal)).append('\n');
    31	        if (discount.signum() > 0) text.append("Desconto: ").append(Money.format(discount)).append('\n');
    32	        text.append("Total: ").append(Money.format(total));
    33	        return text.toString();
    34	    }
    35	}
