     1	package br.com.marealta.reservas.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	public final class Money {
    10	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
    11	
    12	    private Money() {}
    13	
    14	    public static BigDecimal round(BigDecimal value) {
    15	        return value.setScale(2, RoundingMode.HALF_EVEN);
    16	    }
    17	
    18	    /** Formats as "R$ 1.234,56". */
    19	    public static String format(BigDecimal value) {
    20	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
    21	        symbols.setDecimalSeparator(',');
    22	        symbols.setGroupingSeparator('.');
    23	        return "R$ " + new DecimalFormat("#,##0.00", symbols).format(value);
    24	    }
    25	}

