    41	        app.exception(Exception.class, (e, ctx) -> ctx.status(500)
    42	                .json(Map.of("error", "INTERNAL_ERROR", "message", "Erro interno")));
    43	
    44	        app.get("/rooms", ctx -> ctx.json(rooms.all().stream().map(RoomView::of).toList()));
    45	        app.post("/reservations", ctx -> ctx.status(201).json(ReservationView.of(
    46	                reservations.create(ReservationRequestParser.parse(ctx.body())))));
    47	        app.get("/reservations/{id}", ctx -> ctx.json(ReservationView.of(reservations.get(id(ctx)))));
    48	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(ReservationView.of(reservations.confirm(id(ctx)))));
    49	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(ReservationView.of(reservations.cancel(id(ctx)))));
