    52	                ctx.json(ReceiptView.of(Receipt.of(reservations.checkOut(id(ctx))))));
    53	        app.get("/reservations/{id}/document", ctx ->
    54	                ctx.json(ReceiptView.of(Receipt.of(reservations.paidReservation(id(ctx))))));
