     1	package br.com.marealta.reservas.web;
     2	
     3	import br.com.marealta.reservas.domain.DomainException;
     4	import br.com.marealta.reservas.domain.NewReservation;
     5	import br.com.marealta.reservas.domain.RatePlan;
     6	import com.fasterxml.jackson.core.JsonProcessingException;
     7	import com.fasterxml.jackson.databind.JsonNode;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeParseException;
    12	
    13	final class ReservationRequestParser {
    14	    private static final ObjectMapper MAPPER = new ObjectMapper();
    15	
    16	    private ReservationRequestParser() {}
    17	
    18	    static NewReservation parse(String body) {
    19	        JsonNode json;
    20	        try {
    21	            json = MAPPER.readTree(body);
    22	        } catch (JsonProcessingException e) {
    23	            throw DomainException.invalidRequest("O corpo precisa ser um JSON válido");
    24	        }
    25	        if (json == null || !json.isObject()) throw DomainException.invalidRequest("O corpo precisa ser um objeto JSON");
    26	
    27	        LocalDate checkIn = date(json, "checkIn");
    28	        LocalDate checkOut = date(json, "checkOut");
    29	        if (!checkOut.isAfter(checkIn)) throw DomainException.invalidRequest("A saída precisa ser depois da entrada");
    30	        int guests = integer(json, "guests");
    31	        if (guests < 1) throw DomainException.invalidRequest("É preciso ao menos um hóspede");
    32	        return new NewReservation(integer(json, "roomNumber"), text(json, "guestName"), text(json, "guestEmail"),
    33	                text(json, "guestCpf"), checkIn, checkOut, guests, ratePlan(json));
    34	    }
    35	
    36	    private static String text(JsonNode json, String field) {
    37	        JsonNode node = json.get(field);
    38	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    39	            throw DomainException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
    40	        }
    41	        return node.asText();
    42	    }
    43	
    44	    private static int integer(JsonNode json, String field) {
