     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.temporal.ChronoUnit;
     6	
     7	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     8	
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	
    11	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    12	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    13	        BigDecimal subtotal = Money.ZERO;
    14	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    15	            subtotal = subtotal.add(priceOfNight(room, night));
    16	        }
    17	        BigDecimal discount = plan.discountOn(subtotal);
    18	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    19	    }
    20	
    21	    private static BigDecimal priceOfNight(Room room, LocalDate night) {
    22	        BigDecimal rate = room.nightlyRate();
    23	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    24	    }
    25	
    26	    /** From December 15 to the end of February, and all of July. */
    27	    static boolean isHighSeason(LocalDate night) {
    28	        int month = night.getMonthValue();
    29	        return month == 1 || month == 2 || month == 7
    30	                || (month == 12 && night.getDayOfMonth() >= 15);
    31	    }
    32	}
