    23	            throw DomainException.invalidRequest("O corpo precisa ser um JSON válido");
    24	        }
    25	        if (json == null || !json.isObject()) throw DomainException.invalidRequest("O corpo precisa ser um objeto JSON");
    26	
    27	        LocalDate checkIn = date(json, "checkIn");
    28	        LocalDate checkOut = date(json, "checkOut");
    29	        if (!checkOut.isAfter(checkIn)) throw DomainException.invalidRequest("A saída precisa ser depois da entrada");
    30	        int guests = integer(json, "guests");
    31	        if (guests < 1) throw DomainException.invalidRequest("É preciso ao menos um hóspede");
    32	        return new NewReservation(integer(json, "roomNumber"), text(json, "guestName"), text(json, "guestEmail"),
    33	                text(json, "guestCpf"), checkIn, checkOut, guests, ratePlan(json));
